import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import VulnCard from '../components/VulnCard';
import ScoreCircle from '../components/ScoreCircle';
import SeverityChart from '../components/SeverityChart';
import { exportJSON, printReport } from '../utils/exportUtils';

function Report() {
  const [result, setResult] = useState(null);
  const navigate = useNavigate();

  useEffect(() => {
    const stored = sessionStorage.getItem('auditResult');
    if (stored) {
      setResult(JSON.parse(stored));
    } else {
      navigate('/analyzer');
    }
  }, [navigate]);

  if (!result) return null;

  const { findings, securityScore, riskLevel, totalVulnerabilities, highCount, mediumCount, lowCount, language } = result;

  const riskColor = securityScore >= 80 ? 'var(--low)' : securityScore >= 50 ? 'var(--medium)' : 'var(--high)';

  return (
    <div className="page">
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '2rem', flexWrap: 'wrap', gap: '1rem' }}>
        <div className="page-header" style={{ marginBottom: 0 }}>
          <h1>Security Audit Report</h1>
          <p>Language: {language} &nbsp;·&nbsp; Generated: {new Date().toLocaleString()}</p>
        </div>
        <div style={{ display: 'flex', gap: '0.5rem', flexWrap: 'wrap' }}>
          <button className="btn btn-outline" onClick={() => exportJSON(result, result.code, language)}>
            Export JSON
          </button>
          <button className="btn btn-outline" onClick={printReport}>
            Print Report
          </button>
          <button className="btn btn-primary" onClick={() => navigate('/analyzer')}>
            New Audit
          </button>
        </div>
      </div>

      {/* Summary Row */}
      <div style={{ display: 'grid', gridTemplateColumns: 'auto 1fr 1fr', gap: '1.5rem', marginBottom: '1.5rem', alignItems: 'start' }}>
        {/* Score */}
        <div className="card" style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '0.75rem', minWidth: '160px' }}>
          <div className="card-title">Security Score</div>
          <ScoreCircle score={securityScore} />
          <span style={{ fontSize: '0.8rem', color: riskColor, fontWeight: 600 }}>{riskLevel} RISK</span>
        </div>

        {/* Stats */}
        <div className="card">
          <div className="card-title">Findings Summary</div>
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0.75rem' }}>
            <div className="stat-card">
              <div className="stat-num" style={{ color: 'var(--text-primary)' }}>{totalVulnerabilities}</div>
              <div className="stat-label">Total Issues</div>
            </div>
            <div className="stat-card">
              <div className="stat-num" style={{ color: 'var(--high)' }}>{highCount}</div>
              <div className="stat-label">High Severity</div>
            </div>
            <div className="stat-card">
              <div className="stat-num" style={{ color: 'var(--medium)' }}>{mediumCount}</div>
              <div className="stat-label">Medium Severity</div>
            </div>
            <div className="stat-card">
              <div className="stat-num" style={{ color: 'var(--low)' }}>{lowCount}</div>
              <div className="stat-label">Low Severity</div>
            </div>
          </div>
        </div>

        {/* Chart */}
        <div className="card">
          <div className="card-title">Severity Distribution</div>
          <SeverityChart high={highCount} medium={mediumCount} low={lowCount} />
        </div>
      </div>

      {/* Findings Table */}
      {findings.length > 0 && (
        <div className="card" style={{ marginBottom: '1.5rem' }}>
          <div className="card-title">Findings Overview</div>
          <div className="table-wrapper">
            <table>
              <thead>
                <tr>
                  <th>#</th>
                  <th>Vulnerability</th>
                  <th>Severity</th>
                  <th>Line</th>
                  <th>Recommendation</th>
                </tr>
              </thead>
              <tbody>
                {findings.map((f, i) => (
                  <tr key={i}>
                    <td style={{ color: 'var(--text-muted)', fontFamily: 'Share Tech Mono, monospace' }}>
                      {String(i + 1).padStart(2, '0')}
                    </td>
                    <td style={{ fontWeight: 500 }}>{f.name}</td>
                    <td>
                      <span className={`badge badge-${f.severity.toLowerCase()}`}>{f.severity}</span>
                    </td>
                    <td style={{ fontFamily: 'Share Tech Mono, monospace', color: 'var(--text-muted)' }}>
                      {f.lineNumber || '—'}
                    </td>
                    <td style={{ fontSize: '0.8rem', color: 'var(--text-secondary)', maxWidth: '300px' }}>
                      {f.recommendation.substring(0, 80)}...
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* Detailed Findings */}
      <div>
        <h2 style={{ fontFamily: 'Rajdhani, sans-serif', fontSize: '1.2rem', color: 'var(--text-secondary)', textTransform: 'uppercase', letterSpacing: '1px', marginBottom: '1rem' }}>
          Detailed Findings
        </h2>
        {findings.length === 0 ? (
          <div className="card" style={{ textAlign: 'center', padding: '3rem', borderColor: 'rgba(46,213,115,0.3)' }}>
            <div style={{ fontSize: '3rem', marginBottom: '0.75rem' }}>✅</div>
            <h3 style={{ fontFamily: 'Rajdhani, sans-serif', color: 'var(--low)', fontSize: '1.2rem' }}>No Vulnerabilities Found</h3>
            <p style={{ color: 'var(--text-muted)', marginTop: '0.5rem', fontSize: '0.875rem' }}>
              The analyzed code appears to be free of common security issues.
            </p>
          </div>
        ) : (
          findings.map((f, i) => <VulnCard key={i} finding={f} index={i} />)
        )}
      </div>
    </div>
  );
}

export default Report;
