import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { analyzeCode, SAMPLE_VULNERABLE_CODE } from '../utils/vulnDetector';
import axios from 'axios';

const LANGUAGES = [
  { value: 'javascript', label: 'JavaScript' },
  { value: 'python', label: 'Python' },
  { value: 'java', label: 'Java' },
  { value: 'cpp', label: 'C++' },
  { value: 'php', label: 'PHP' },
];

function Analyzer() {
  const [code, setCode] = useState('');
  const [language, setLanguage] = useState('javascript');
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();

  const handleAnalyze = async () => {
    if (!code.trim()) return;
    setLoading(true);

    // Run frontend detection
    const result = analyzeCode(code);

    // Try to save to backend (optional - won't break if backend is offline)
    try {
      await axios.post('/api/analyze/save', { code, language });
    } catch (e) {
      // Backend offline - continue with frontend-only results
    }

    // Store result and navigate to report
    sessionStorage.setItem('auditResult', JSON.stringify({ ...result, code, language }));
    setLoading(false);
    navigate('/report');
  };

  const handleLoadSample = () => {
    setCode(SAMPLE_VULNERABLE_CODE);
    setLanguage('javascript');
  };

  const handleClear = () => setCode('');

  return (
    <div className="page">
      <div className="page-header">
        <h1>Code Analyzer</h1>
        <p>Paste your source code below to detect security vulnerabilities</p>
      </div>

      {/* Controls */}
      <div style={{ display: 'flex', gap: '0.75rem', marginBottom: '1rem', flexWrap: 'wrap', alignItems: 'center' }}>
        <select value={language} onChange={(e) => setLanguage(e.value || e.target.value)}>
          {LANGUAGES.map((l) => (
            <option key={l.value} value={l.value}>{l.label}</option>
          ))}
        </select>
        <button className="btn btn-outline" onClick={handleLoadSample}>
          Load Sample Vulnerable Code
        </button>
        <button className="btn btn-danger" onClick={handleClear}>
          Clear
        </button>
      </div>

      {/* Code Editor */}
      <div className="card" style={{ padding: '0', marginBottom: '1rem' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '0.75rem 1rem', borderBottom: '1px solid var(--border)' }}>
          <span style={{ fontFamily: 'Share Tech Mono, monospace', fontSize: '0.8rem', color: 'var(--text-muted)' }}>
            {language} &nbsp;·&nbsp; {code.split('\n').length} lines
          </span>
          <span style={{ fontSize: '0.75rem', color: 'var(--text-muted)' }}>
            {code.length} characters
          </span>
        </div>
        <textarea
          value={code}
          onChange={(e) => setCode(e.target.value)}
          placeholder={`// Paste your ${language} code here...\n// Or click "Load Sample Vulnerable Code" to see a demo`}
          style={{
            width: '100%',
            minHeight: '420px',
            background: '#020810',
            border: 'none',
            borderRadius: '0 0 var(--radius-lg) var(--radius-lg)',
            color: '#7ec8e3',
            fontFamily: 'Share Tech Mono, monospace',
            fontSize: '0.875rem',
            padding: '1.25rem',
            resize: 'vertical',
            outline: 'none',
            lineHeight: '1.7',
          }}
          spellCheck={false}
        />
      </div>

      {/* Analyze Button */}
      <div style={{ display: 'flex', justifyContent: 'flex-end' }}>
        <button
          className="btn btn-primary"
          onClick={handleAnalyze}
          disabled={!code.trim() || loading}
          style={{ padding: '0.75rem 2.5rem', fontSize: '1rem' }}
        >
          {loading ? (
            <><span className="spinner"></span> Analyzing...</>
          ) : (
            '🔍 Analyze Code'
          )}
        </button>
      </div>
    </div>
  );
}

export default Analyzer;
