import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import SeverityChart from '../components/SeverityChart';

function Dashboard() {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const navigate = useNavigate();

  useEffect(() => {
    axios.get('/api/dashboard')
      .then((res) => {
        setData(res.data.data);
        setLoading(false);
      })
      .catch(() => {
        setError('Backend not connected. Run the server to see dashboard data.');
        setLoading(false);
      });
  }, []);

  if (loading) {
    return (
      <div className="page" style={{ textAlign: 'center', paddingTop: '5rem' }}>
        <span className="spinner"></span>
        <span style={{ color: 'var(--text-muted)' }}>Loading dashboard...</span>
      </div>
    );
  }

  if (error) {
    return (
      <div className="page">
        <div className="page-header">
          <h1>Dashboard</h1>
        </div>
        <div className="card" style={{ textAlign: 'center', padding: '3rem', borderColor: 'var(--neon-border)' }}>
          <div style={{ fontSize: '2.5rem', marginBottom: '1rem' }}>⚠️</div>
          <h3 style={{ fontFamily: 'Rajdhani, sans-serif', marginBottom: '0.5rem' }}>Backend Not Connected</h3>
          <p style={{ color: 'var(--text-muted)', marginBottom: '1.5rem', fontSize: '0.875rem' }}>
            {error}
          </p>
          <button className="btn btn-primary" onClick={() => navigate('/analyzer')}>
            Start Analyzing Code
          </button>
        </div>
      </div>
    );
  }

  const { totalAudits, severityCounts, recentAudits, languageStats } = data;

  return (
    <div className="page">
      <div className="page-header">
        <h1>Dashboard</h1>
        <p>Overview of all security audits performed</p>
      </div>

      {/* Stats */}
      <div className="stat-grid" style={{ gridTemplateColumns: 'repeat(4, 1fr)', marginBottom: '1.5rem' }}>
        <div className="stat-card">
          <div className="stat-num" style={{ color: 'var(--neon)' }}>{totalAudits}</div>
          <div className="stat-label">Total Audits</div>
        </div>
        <div className="stat-card">
          <div className="stat-num" style={{ color: 'var(--high)' }}>{severityCounts?.totalHigh || 0}</div>
          <div className="stat-label">High Severity</div>
        </div>
        <div className="stat-card">
          <div className="stat-num" style={{ color: 'var(--medium)' }}>{severityCounts?.totalMedium || 0}</div>
          <div className="stat-label">Medium Severity</div>
        </div>
        <div className="stat-card">
          <div className="stat-num" style={{ color: 'var(--low)' }}>{severityCounts?.totalLow || 0}</div>
          <div className="stat-label">Low Severity</div>
        </div>
      </div>

      <div className="grid-2" style={{ marginBottom: '1.5rem' }}>
        {/* Chart */}
        <div className="card">
          <div className="card-title">Severity Distribution (All Audits)</div>
          <SeverityChart
            high={severityCounts?.totalHigh || 0}
            medium={severityCounts?.totalMedium || 0}
            low={severityCounts?.totalLow || 0}
          />
        </div>

        {/* Language stats */}
        <div className="card">
          <div className="card-title">Audits by Language</div>
          {languageStats && languageStats.length > 0 ? (
            languageStats.map((l) => (
              <div key={l._id} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '0.6rem 0', borderBottom: '1px solid var(--border)' }}>
                <span style={{ fontFamily: 'Share Tech Mono, monospace', color: 'var(--neon)', fontSize: '0.875rem' }}>{l._id}</span>
                <span style={{ color: 'var(--text-secondary)', fontSize: '0.875rem' }}>{l.count} audit{l.count !== 1 ? 's' : ''}</span>
              </div>
            ))
          ) : (
            <p style={{ color: 'var(--text-muted)', fontSize: '0.875rem' }}>No data yet.</p>
          )}
        </div>
      </div>

      {/* Recent Audits */}
      <div className="card">
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1rem' }}>
          <div className="card-title" style={{ marginBottom: 0 }}>Recent Audits</div>
          <button className="btn btn-outline" style={{ fontSize: '0.8rem', padding: '0.3rem 0.75rem' }} onClick={() => navigate('/analyzer')}>
            + New Audit
          </button>
        </div>
        {recentAudits && recentAudits.length > 0 ? (
          <div className="table-wrapper">
            <table>
              <thead>
                <tr>
                  <th>Date</th>
                  <th>Language</th>
                  <th>Score</th>
                  <th>Risk</th>
                  <th>Issues</th>
                  <th>High</th>
                </tr>
              </thead>
              <tbody>
                {recentAudits.map((a) => (
                  <tr key={a._id}>
                    <td style={{ fontFamily: 'Share Tech Mono, monospace', fontSize: '0.8rem', color: 'var(--text-muted)' }}>
                      {new Date(a.createdAt).toLocaleDateString()}
                    </td>
                    <td style={{ color: 'var(--neon)', fontFamily: 'Share Tech Mono, monospace', fontSize: '0.875rem' }}>
                      {a.language}
                    </td>
                    <td style={{ fontWeight: 600 }}>
                      <span style={{ color: a.securityScore >= 70 ? 'var(--low)' : a.securityScore >= 40 ? 'var(--medium)' : 'var(--high)' }}>
                        {a.securityScore}
                      </span>
                    </td>
                    <td>
                      <span className={`badge badge-${a.riskLevel === 'Critical' || a.riskLevel === 'High' ? 'high' : a.riskLevel === 'Medium' ? 'medium' : 'low'}`}>
                        {a.riskLevel}
                      </span>
                    </td>
                    <td>{a.totalVulnerabilities}</td>
                    <td style={{ color: 'var(--high)' }}>{a.highCount}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        ) : (
          <p style={{ color: 'var(--text-muted)', fontSize: '0.875rem', textAlign: 'center', padding: '2rem' }}>
            No audits saved yet. Analyze some code to populate this dashboard.
          </p>
        )}
      </div>
    </div>
  );
}

export default Dashboard;
